#!/usr/bin/env python3

"""
OCI Weekly Health Check
--------------------------------

Purpose:
    Collect OCI tenancy resources for the last 7 days (configurable)
    and generate:

        1. HTML health report, including prioritized recommendations
        2. JSON inventory (same data, plus the recommendations list)

    Cost, utilization (average and peak), OCI announcements and new
    resources all cover the same trailing window; cost is compared with
    the window immediately before it (week-over-week by default).

Inspired by Oracle OCI ShowOCI approach.

Authentication:
    ~/.oci/config

Example (weekly report, default profile):
    python3 oci_health_check.py

Specific profile:
    python3 oci_health_check.py --profile DEFAULT

Only selected region:
    python3 oci_health_check.py --region me-jeddah-1

Different reporting window (e.g. two weeks):
    python3 oci_health_check.py --days 14

Customer-facing report (recommended when sending to a customer):
    python3 oci_health_check.py --profile CUSTOMER_A --customer-name "OCI Customer A"
"""

import argparse
import base64
import concurrent.futures
import datetime
import io
import json
import os
import re
import sys
import threading
import traceback
import warnings

# The 'strict' parameter FutureWarning comes from urllib3 being called
# internally by the OCI SDK's HTTP layer; it's not something this script
# controls and clutters the console on every run. Silence just this one.
warnings.filterwarnings(
    "ignore",
    message=".*'strict' parameter is no longer needed.*",
    category=FutureWarning
)

import oci
from oci.announcements_service import AnnouncementClient

# The seven-day cost chart renders as a proper matplotlib figure when the
# library is available (a much more polished, customer-facing result than
# a hand-drawn SVG polyline), and falls back to a lightweight inline SVG
# line chart if matplotlib isn't installed in the running environment, so
# report generation never hard-fails over an optional dependency.
try:
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.ticker as mticker
    MATPLOTLIB_AVAILABLE = True
except ImportError:
    MATPLOTLIB_AVAILABLE = False


# ============================================================
# CONFIGURATION
# ============================================================

# The report is a weekly health check: cost, utilization, announcements
# and "new resources" all cover the same trailing window (the last N full
# days), and cost is compared against the N days immediately before it
# (week-over-week by default). Individual windows can still be overridden
# from the command line.
DEFAULT_REPORT_PERIOD_DAYS = 7
DEFAULT_BACKUP_MAX_AGE_DAYS = 2
DEFAULT_ANNOUNCEMENT_DAYS = DEFAULT_REPORT_PERIOD_DAYS
DEFAULT_COST_ANALYSIS_DAYS = DEFAULT_REPORT_PERIOD_DAYS
DEFAULT_UTILIZATION_DAYS = DEFAULT_REPORT_PERIOD_DAYS

# Utilization thresholds. "avg" is the mean of hourly means over the
# whole period (sustained load); "peak" is the highest hourly mean.
CPU_HIGH_PERCENT = 80
MEMORY_HIGH_PERCENT = 85
DISK_HIGH_PERCENT = 80
IDLE_CPU_AVG_PERCENT = 5
IDLE_CPU_PEAK_PERCENT = 20

# Cost recommendation thresholds.
COST_INCREASE_WARN_PERCENT = 10
COST_INCREASE_HIGH_PERCENT = 25
COST_DAILY_SPIKE_FACTOR = 1.5

# Resource types that are recurring, automatically generated artifacts of
# infrastructure that already exists (e.g. daily policy-based backups).
# They always carry a recent creation date, so counting them as "new
# resources" would bury genuinely new infrastructure (VMs, volumes,
# databases) under routine backup churn.
NON_INFRASTRUCTURE_RESOURCE_TYPES = {
    "Block Volume Backup",
    "Boot Volume Backup"
}
DEFAULT_OCI_PROFILE = ["EMICOOL"]
OCI_CLIENT_TIMEOUT = (20, 60)

# Embedded so the HTML report renders correctly with no network access and
# no dependency on an external asset host (important when the report is
# emailed to a customer or opened behind a restrictive proxy). White/light
# variant of the ZainTECH logo for use on the dark report header.
ZAINTECH_LOGO_BASE64 = ""


# ============================================================
# HELPERS
# ============================================================

def now_utc():
    return datetime.datetime.now(datetime.timezone.utc)


def iso(value):
    if value is None:
        return None

    if isinstance(value, datetime.datetime):
        return value.isoformat()

    return str(value)


def safe(value, default=""):
    return value if value is not None else default


# Known, well-understood OCI error signatures that are worth explaining
# in plain language rather than leaving the customer to interpret a raw
# API error. Matched case-insensitively against the error text.
KNOWN_ERROR_HINTS = [
    (
        "please go to your home region",
        "The tenancy's billing/usage home region may differ from the "
        "IAM home region this script detected. Confirm the true home "
        "region via the OCI Console (Governance & Administration > "
        "Tenancy Management > Tenancy Details) or by running "
        "'oci iam region-subscription list', and confirm the calling "
        "user/group has a policy granting 'read usage-report in "
        "tenancy'."
    ),
    (
        "authorization failed or requested resource not found",
        "For Cloud Guard specifically, a 404 on list_problems usually "
        "means Cloud Guard has never been enabled for this tenancy "
        "rather than a permissions issue -- check the Configuration "
        "status reported for Cloud Guard above."
    ),
    (
        "connecttimeouterror",
        "This is a network connectivity issue (DNS/firewall/proxy) "
        "between the machine running this script and the OCI regional "
        "endpoint, not an OCI permissions or configuration problem. "
        "Verify outbound HTTPS (443) access to the specific hostname "
        "in the request endpoint above -- e.g. from PowerShell: "
        "'Test-NetConnection <hostname> -Port 443'. A different "
        "network (no VPN/proxy, or a different site) reaching this "
        "same region successfully would confirm it."
    ),
    (
        "max retries exceeded",
        "This is a network connectivity issue (DNS/firewall/proxy) "
        "between the machine running this script and the OCI regional "
        "endpoint, not an OCI permissions or configuration problem. "
        "Verify outbound HTTPS (443) access to the specific hostname "
        "in the request endpoint above -- e.g. from PowerShell: "
        "'Test-NetConnection <hostname> -Port 443'. A different "
        "network (no VPN/proxy, or a different site) reaching this "
        "same region successfully would confirm it."
    ),
]


def error_hint(error_text):

    lowered = error_text.lower()

    for signature, hint in KNOWN_ERROR_HINTS:
        if signature in lowered:
            return hint

    return None


# OS family groupings used for the customer-facing OS inventory summary.
# Matched case-insensitively against whatever the image's operating
# system string reports (e.g. "Oracle Linux 8", "Windows Server 2019",
# "Canonical Ubuntu 22.04"). Anything unrecognized (custom/BYOL images,
# or a lookup that failed) falls into "Other / Custom" rather than being
# guessed at.
LINUX_OS_KEYWORDS = [
    "linux", "ubuntu", "centos", "oracle", "debian",
    "red hat", "redhat", "suse", "rocky", "alma", "unix"
]


def classify_os_family(os_info):

    if not os_info or os_info == "Unknown":
        return "Other / Custom"

    lowered = os_info.lower()

    if "windows" in lowered:
        return "Windows"

    if any(keyword in lowered for keyword in LINUX_OS_KEYWORDS):
        return "Linux"

    return "Other / Custom"


def get_name(obj):
    """
    Try common OCI name attributes.
    """
    for attr in [
        "display_name",
        "name",
        "instance_name",
        "hostname_label",
    ]:
        value = getattr(obj, attr, None)
        if value:
            return value

    return "N/A"


def lifecycle(obj):
    return safe(
        getattr(obj, "lifecycle_state", None),
        "UNKNOWN"
    )


def short_ocid(ocid):
    if not ocid:
        return ""

    if len(ocid) <= 32:
        return ocid

    return ocid[:16] + "..." + ocid[-10:]


# ============================================================
# OCI HEALTH CHECK
# ============================================================

class OCIHealthCheck:

    def __init__(
        self,
        profile=DEFAULT_OCI_PROFILE,
        region=None,
        announcement_days=DEFAULT_ANNOUNCEMENT_DAYS,
        backup_max_age_days=DEFAULT_BACKUP_MAX_AGE_DAYS,
        config_file=None,
        max_workers=6,
        customer_name=None,
        cost_analysis_days=DEFAULT_COST_ANALYSIS_DAYS,
        utilization_days=DEFAULT_UTILIZATION_DAYS
    ):

        self.profile = profile
        # Customer-facing display name shown on the report. Falls back to
        # the OCI profile alias, but a proper --customer-name should always
        # be passed for reports leaving ZainTECH, since profile aliases are
        # internal identifiers and not meant for an external audience.
        self.customer_name = customer_name or profile
        self.region_filter = region
        self.announcement_days = announcement_days
        self.backup_max_age_days = backup_max_age_days
        self.cost_analysis_days = max(1, min(int(cost_analysis_days), 90))
        self.utilization_days = max(1, min(int(utilization_days), 90))
        self.max_workers = max(1, min(int(max_workers), 12))
        self.config_file = os.path.expanduser(
            config_file
            or os.environ.get(
                "OCI_CONFIG_FILE",
                "~/.oci/config"
            )
        )

        self.errors = []
        self.resource_costs = {}
        self.state_lock = threading.Lock()
        self.policy_cache = {}
        self.image_os_cache = {}
        self.instance_name_cache = {}
        self.ad_cache = {}
        self.namespace_cache = None
        self.scan_regions = []

        try:
            self.config = oci.config.from_file(
                self.config_file,
                profile
            )
        except oci.exceptions.ConfigFileNotFound as exc:
            raise RuntimeError(
                "Cannot read OCI config file at "
                f"{self.config_file}. Confirm that it exists and "
                "is readable, or provide --config-file."
            ) from exc

        self.tenancy_id = self.config["tenancy"]

        self.home_region = self.config.get("region")

        self.report_time = now_utc()

        self.data = {
            "metadata": {},
            "summary": {},
            "regions": [],
            "compartments": [],
            "iam": {},
            "resources": [],
            "alarms": [],
            "announcements": [],
            "cloud_guard": {},
            "backup_issues": [],
            "replication": [],
            "utilization": [],
            "cost": {
                "status": "NOT COLLECTED",
                "currency": "USD",
                "daily": [],
                "total": 0
            },
            "resource_search": [],
            "errors": []
        }

        self.identity = oci.identity.IdentityClient(
            self.config,
            retry_strategy=oci.retry.DEFAULT_RETRY_STRATEGY,
            timeout=OCI_CLIENT_TIMEOUT
        )


    # ========================================================
    # ERROR HANDLING
    # ========================================================

    def record_error(self, section, region, compartment, error):

        error_text = str(error)
        hint = error_hint(error_text)

        item = {
            "section": section,
            "region": region,
            "compartment": compartment,
            "error": error_text,
            "hint": hint
        }

        with self.state_lock:
            self.errors.append(item)

        print(
            f"[WARNING] {section} | "
            f"{region} | "
            f"{compartment} | "
            f"{error_text}"
        )

        if hint:
            print(f"[HINT] {hint}")


    # ========================================================
    # GENERIC PAGINATION
    # ========================================================

    def get_all(self, func, **kwargs):
        return oci.pagination.list_call_get_all_results(
            func,
            **kwargs
        ).data


    # ========================================================
    # REGIONS
    # ========================================================

    def get_regions(self):

        print("[INFO] Discovering subscribed regions...")

        regions = self.get_all(
            self.identity.list_region_subscriptions,
            tenancy_id=self.tenancy_id
        )

        # The tenancy's real home region is never hard-coded here -- it's
        # derived at runtime so this script works unmodified across any
        # number of tenancies/accounts. Two independent signals from OCI
        # are cross-checked, since relying on just one has proven fragile
        # in practice:
        #   1. `is_home_region` on each region subscription.
        #   2. `home_region_key` on the tenancy record itself (the same
        #      3-letter key, e.g. "DXB", shown as "Home region" in the
        #      OCI Console), matched back to a region name via
        #      `region_key` on the subscriptions list.
        # Some operations (Usage/Cost API, Cloud Guard reporting) only
        # succeed against the true home region, which can differ from
        # whatever `region=` happens to be set in the local OCI config
        # profile (e.g. a profile pointed at a working region for
        # convenience), so the API is trusted over the local config.

        home_by_flag = next(
            (
                region.region_name
                for region in regions
                if getattr(region, "is_home_region", False)
            ),
            None
        )

        home_by_key = None

        try:
            tenancy = self.identity.get_tenancy(
                tenancy_id=self.tenancy_id
            ).data

            home_region_key = getattr(tenancy, "home_region_key", None)

            if home_region_key:
                home_by_key = next(
                    (
                        region.region_name
                        for region in regions
                        if getattr(region, "region_key", None)
                        == home_region_key
                    ),
                    None
                )

        except Exception as exc:
            print(
                f"[WARNING] Could not look up tenancy home_region_key "
                f"for cross-check: {exc}"
            )

        if home_by_flag and home_by_key and home_by_flag != home_by_key:
            print(
                f"[WARNING] Home region signals disagree: "
                f"is_home_region says '{home_by_flag}', tenancy "
                f"home_region_key says '{home_by_key}'. Using the "
                f"tenancy record as authoritative."
            )

        api_home_region = home_by_key or home_by_flag

        if api_home_region and api_home_region != self.home_region:
            print(
                f"[INFO] Home region reported by OCI is "
                f"'{api_home_region}'; overriding config-derived "
                f"'{self.home_region}'."
            )
            self.home_region = api_home_region

        if not api_home_region:
            print(
                f"[WARNING] OCI did not report a usable home region "
                f"signal; falling back to config-derived region "
                f"'{self.home_region}' for home-region-only calls "
                f"(Cloud Guard, Billing/Cost). If those still fail, "
                f"verify the true home region with "
                f"'oci iam region-subscription list'."
            )

        print(
            f"[INFO] Home region for Cloud Guard / Billing & Cost "
            f"calls: '{self.home_region}'"
        )

        result = []

        for region in regions:

            if str(region.status).upper() != "READY":
                continue

            region_name = region.region_name

            if self.region_filter:
                if region_name != self.region_filter:
                    continue

            result.append({
                "region": region_name,
                "status": region.status,
                "is_home_region": (
                    region_name == self.home_region
                )
            })

        return result


    # ========================================================
    # COMPARTMENTS
    # ========================================================

    def get_compartments(self):

        print("[INFO] Discovering compartments...")

        compartments = []

        # Root tenancy
        compartments.append({
            "id": self.tenancy_id,
            "name": "ROOT",
            "parent_id": None,
            "path": "ROOT",
            "state": "ACTIVE"
        })

        try:

            children = self.get_all(
                self.identity.list_compartments,
                compartment_id=self.tenancy_id,
                compartment_id_in_subtree=True,
                access_level="ANY"
            )

            for comp in children:

                if comp.lifecycle_state != "ACTIVE":
                    continue

                compartments.append({
                    "id": comp.id,
                    "name": comp.name,
                    "parent_id": comp.compartment_id,
                    "path": comp.name,
                    "state": comp.lifecycle_state
                })

        except Exception as exc:

            self.record_error(
                "Compartments",
                self.home_region,
                "ROOT",
                exc
            )

        # Build paths
        lookup = {
            c["id"]: c
            for c in compartments
        }

        for comp in compartments:

            path = []

            current = comp

            while current:

                path.insert(0, current["name"])

                parent = current.get("parent_id")

                if not parent:
                    break

                current = lookup.get(parent)

                if not current:
                    break

            comp["path"] = " / ".join(path)

        self.data["compartments"] = compartments

        return compartments


    # ========================================================
    # CLIENT FACTORY
    # ========================================================

    def clients(self, region):

        config = self.config.copy()
        config["region"] = region

        retry_strategy = oci.retry.DEFAULT_RETRY_STRATEGY

        return {
            "compute":
                oci.core.ComputeClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "block":
                oci.core.BlockstorageClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "network":
                oci.core.VirtualNetworkClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "lb":
                oci.load_balancer.LoadBalancerClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "nlb":
                oci.network_load_balancer.NetworkLoadBalancerClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "monitoring":
                oci.monitoring.MonitoringClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "notifications":
                oci.ons.NotificationControlPlaneClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "object":
                oci.object_storage.ObjectStorageClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "file":
                oci.file_storage.FileStorageClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "database":
                oci.database.DatabaseClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "resource_search":
                oci.resource_search.ResourceSearchClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                ),

            "cloud_guard":
                oci.cloud_guard.CloudGuardClient(
                    config,
                    retry_strategy=retry_strategy,
                    timeout=OCI_CLIENT_TIMEOUT
                )
        }


    def endpoint_regions(self):

        regions = [self.home_region]
        regions.extend(self.scan_regions)

        return list(dict.fromkeys(
            region for region in regions if region
        ))


    def endpoint_call(self, client_factory, operation, regions=None):

        last_error = None

        for endpoint_region in (regions or self.endpoint_regions()):

            config = self.config.copy()
            config["region"] = endpoint_region

            try:
                client = client_factory(config)
                return operation(client), None
            except Exception as exc:
                last_error = exc

        return None, last_error


    # ========================================================
    # CLOUD GUARD
    # ========================================================

    def collect_cloud_guard(self):

        print("[INFO] Collecting Cloud Guard status...")

        # Cloud Guard's configuration/problems endpoints are scoped to the
        # tenancy's home region only. Looping through every scanned region
        # (as this used to do) wastes calls, produces a 404 from every
        # non-home region, and — since only the last error survives the
        # loop — can hide the one error that actually matters. Call the
        # home region once and report on that alone.

        config = self.config.copy()
        config["region"] = self.home_region

        try:

            client = oci.cloud_guard.CloudGuardClient(
                config,
                retry_strategy=oci.retry.DEFAULT_RETRY_STRATEGY,
                timeout=OCI_CLIENT_TIMEOUT
            )

            configuration = client.get_configuration(
                compartment_id=self.tenancy_id
            ).data

            status = safe(
                getattr(configuration, "status", None),
                "UNKNOWN"
            )

            # When Cloud Guard has never been enabled for the tenancy,
            # list_problems() reliably returns a 404 ("Authorization
            # failed or requested resource not found") because there is
            # no Cloud Guard reporting region configured yet. That is
            # Cloud Guard genuinely being off, not a collection failure
            # — report the real status instead of surfacing a confusing
            # error for an expected condition.
            if status != "ENABLED":

                self.data["cloud_guard"] = {
                    "status": status,
                    "targets": 0,
                    "problems": 0
                }

                return self.data["cloud_guard"]

            targets = self.get_all(
                client.list_targets,
                compartment_id=self.tenancy_id
            )

            problems = self.get_all(
                client.list_problems,
                compartment_id=self.tenancy_id
            )

            self.data["cloud_guard"] = {
                "status": status,
                "targets": len(targets),
                "problems": len(problems)
            }

            return self.data["cloud_guard"]

        except Exception as exc:

            self.record_error(
                "Cloud Guard",
                self.home_region,
                "ROOT",
                exc
            )

            self.data["cloud_guard"] = {
                "status": "UNAVAILABLE",
                "targets": 0,
                "problems": 0
            }

        return self.data["cloud_guard"]


    # ========================================================
    # COMPUTE
    # ========================================================

    def get_instance_os(self, compute_client, image_id):

        if not image_id:
            return "Unknown"

        with self.state_lock:
            cached = self.image_os_cache.get(image_id)

        if cached is not None:
            return cached

        try:
            image = compute_client.get_image(image_id).data
            os_info = (
                f"{safe(getattr(image, 'operating_system', ''), '')} "
                f"{safe(getattr(image, 'operating_system_version', ''), '')}"
            ).strip()
            os_info = os_info or "Unknown"
        except Exception:
            os_info = "Unknown"

        with self.state_lock:
            self.image_os_cache[image_id] = os_info

        return os_info


    def get_instance_network_info(
        self,
        compute_client,
        network_client,
        compartment_id,
        instance_id
    ):

        try:
            attachments = self.get_all(
                compute_client.list_vnic_attachments,
                compartment_id=compartment_id,
                instance_id=instance_id
            )

            attached = [
                attachment for attachment in attachments
                if str(
                    safe(getattr(attachment, "lifecycle_state", ""), "")
                ).upper() == "ATTACHED"
            ]

            if not attached:
                return {
                    "private_ip": "No VNIC",
                    "public_ip": "No VNIC",
                    "vnic_count": 0
                }

            vnic = network_client.get_vnic(attached[0].vnic_id).data

            return {
                "private_ip": safe(
                    getattr(vnic, "private_ip", None), "Unknown"
                ),
                "public_ip": safe(
                    getattr(vnic, "public_ip", None), "None"
                ),
                "vnic_count": len(attached)
            }

        except Exception:
            return {
                "private_ip": "Unknown",
                "public_ip": "Unknown",
                "vnic_count": 0
            }


    def collect_compute(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        try:

            instances = self.get_all(
                clients["compute"].list_instances,
                compartment_id=compartment["id"]
            )

            for instance in instances:

                with self.state_lock:
                    self.instance_name_cache[instance.id] = get_name(
                        instance
                    )

                instance_os = self.get_instance_os(
                    clients["compute"],
                    getattr(instance, "image_id", None)
                )

                item = {
                    "resource_type": "Compute Instance",
                    "region": region,
                    "compartment": compartment["path"],
                    "compartment_id": compartment["id"],
                    "name": get_name(instance),
                    "id": instance.id,
                    "state": lifecycle(instance),
                    "shape": safe(
                        getattr(instance, "shape", None)
                    ),
                    "availability_domain":
                        safe(
                            getattr(
                                instance,
                                "availability_domain",
                                None
                            )
                        ),
                    "time_created":
                        iso(
                            getattr(
                                instance,
                                "time_created",
                                None
                            )
                        ),
                    "os": instance_os,
                    "os_family": classify_os_family(instance_os),
                    "ocpus": safe(
                        getattr(
                            getattr(instance, "shape_config", None),
                            "ocpus",
                            None
                        ),
                        0
                    ),
                    "memory_gb": safe(
                        getattr(
                            getattr(instance, "shape_config", None),
                            "memory_in_gbs",
                            None
                        ),
                        0
                    )
                }

                item.update(
                    self.get_instance_network_info(
                        clients["compute"],
                        clients["network"],
                        compartment["id"],
                        instance.id
                    )
                )

                if item["state"] == "RUNNING":
                    item.update(
                        self.get_instance_utilization(
                            clients["monitoring"],
                            instance.id,
                            region,
                            compartment["path"],
                            compartment["id"]
                        )
                    )

                result.append(item)

        except Exception as exc:

            self.record_error(
                "Compute",
                region,
                compartment["path"],
                exc
            )

        return result


    # ========================================================
    # BLOCK STORAGE
    # ========================================================

    def get_availability_domains(self, region):

        with self.state_lock:
            cached = self.ad_cache.get(region)

        if cached is not None:
            return cached

        try:
            config = self.config.copy()
            config["region"] = region

            identity_client = oci.identity.IdentityClient(
                config,
                retry_strategy=oci.retry.DEFAULT_RETRY_STRATEGY,
                timeout=OCI_CLIENT_TIMEOUT
            )

            ads = [
                ad.name for ad in self.get_all(
                    identity_client.list_availability_domains,
                    compartment_id=self.tenancy_id
                )
            ]

        except Exception as exc:
            self.record_error(
                "Availability Domains",
                region,
                "ROOT",
                exc
            )
            ads = []

        with self.state_lock:
            self.ad_cache[region] = ads

        return ads


    def get_instance_name_cached(self, compute_client, instance_id):

        if not instance_id:
            return "N/A"

        with self.state_lock:
            cached = self.instance_name_cache.get(instance_id)

        if cached is not None:
            return cached

        try:
            name = get_name(compute_client.get_instance(instance_id).data)
        except Exception:
            name = "Unknown"

        with self.state_lock:
            self.instance_name_cache[instance_id] = name

        return name


    def get_block_volume_attachments(self, compute_client, compartment_id):

        attachments = {}

        try:
            for attachment in self.get_all(
                compute_client.list_volume_attachments,
                compartment_id=compartment_id
            ):
                if str(
                    safe(getattr(attachment, "lifecycle_state", ""), "")
                ).upper() != "ATTACHED":
                    continue

                attachments[attachment.volume_id] = {
                    "instance_id": attachment.instance_id,
                    "attachment_type": safe(
                        getattr(attachment, "attachment_type", None),
                        "UNKNOWN"
                    ).upper()
                }
        except Exception:
            pass

        return attachments


    def get_boot_volume_attachments(
        self,
        compute_client,
        compartment_id,
        availability_domains
    ):

        attachments = {}

        for ad in availability_domains:
            try:
                for attachment in self.get_all(
                    compute_client.list_boot_volume_attachments,
                    compartment_id=compartment_id,
                    availability_domain=ad
                ):
                    if str(
                        safe(
                            getattr(attachment, "lifecycle_state", ""), ""
                        )
                    ).upper() != "ATTACHED":
                        continue

                    attachments[attachment.boot_volume_id] = (
                        attachment.instance_id
                    )
            except Exception:
                pass

        return attachments


    def collect_storage(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        block_attachments = self.get_block_volume_attachments(
            clients["compute"],
            compartment["id"]
        )

        boot_attachments = self.get_boot_volume_attachments(
            clients["compute"],
            compartment["id"],
            self.get_availability_domains(region)
        )

        def backup_policy(volume_id, volume_name):

            with self.state_lock:
                cached_policy = self.policy_cache.get(volume_id)

            if cached_policy is not None:
                return cached_policy

            try:

                # get_volume_backup_policy_asset_assignment always
                # returns a LIST (at most one item per the OCI SDK
                # docs), never a single object -- and OCI returns an
                # empty list for "no policy assigned" rather than a
                # 404. Treating the list as a single object (as this
                # used to do) meant `policy_id` was always None and
                # every volume was silently reported as ATTACHED.
                assignments = clients[
                    "block"
                ].get_volume_backup_policy_asset_assignment(
                    asset_id=volume_id
                ).data

                if not assignments:

                    with self.state_lock:
                        self.data["backup_issues"].append({
                            "region": region,
                            "compartment": compartment["path"],
                            "name": volume_name,
                            "reason": "No backup policy is attached"
                        })

                    result = {
                        "backup_policy_status": "NOT_ATTACHED",
                        "backup_policy_id": None,
                        "backup_policy_name": None
                    }

                    with self.state_lock:
                        self.policy_cache[volume_id] = result

                    return result

                assignment = assignments[0]

                policy_id = getattr(
                    assignment,
                    "policy_id",
                    None
                )

                policy_name = None

                if policy_id:

                    with self.state_lock:
                        policy_name = self.policy_cache.get(
                            policy_id
                        )

                    if policy_name is None:
                        policy_name = get_name(
                            clients[
                                "block"
                            ].get_volume_backup_policy(
                                policy_id=policy_id
                            ).data
                        )

                        with self.state_lock:
                            self.policy_cache[
                                policy_id
                            ] = policy_name

                result = {
                    "backup_policy_status": "ATTACHED",
                    "backup_policy_id": policy_id,
                    "backup_policy_name": policy_name
                }

                with self.state_lock:
                    self.policy_cache[volume_id] = result

                return result

            except oci.exceptions.ServiceError as exc:

                if exc.status == 404:

                    with self.state_lock:
                        self.data["backup_issues"].append({
                            "region": region,
                            "compartment": compartment["path"],
                            "name": volume_name,
                            "reason": "No backup policy is attached"
                        })

                    result = {
                        "backup_policy_status": "NOT_ATTACHED",
                        "backup_policy_id": None,
                        "backup_policy_name": None
                    }

                    with self.state_lock:
                        self.policy_cache[volume_id] = result

                    return result

                self.record_error(
                    "Backup Policy",
                    region,
                    compartment["path"],
                    exc
                )

            return {
                "backup_policy_status": "UNKNOWN",
                "backup_policy_id": None,
                "backup_policy_name": None
            }

        # ----------------------------------------------------
        # Block Volumes
        # ----------------------------------------------------

        try:

            volumes = self.get_all(
                clients["block"].list_volumes,
                compartment_id=compartment["id"]
            )

            for volume in volumes:

                attachment_info = block_attachments.get(volume.id)

                if attachment_info:
                    attachment_status = "ATTACHED"
                    attachment_type = attachment_info["attachment_type"]
                    attached_instance = self.get_instance_name_cached(
                        clients["compute"],
                        attachment_info["instance_id"]
                    )
                else:
                    attachment_status = "DETACHED"
                    attachment_type = "N/A"
                    attached_instance = "N/A"

                result.append({
                    "resource_type": "Block Volume",
                    "region": region,
                    "compartment": compartment["path"],
                    "name": get_name(volume),
                    "id": volume.id,
                    "state": lifecycle(volume),
                    "size_gb": safe(
                        getattr(
                            volume,
                            "size_in_gbs",
                            None
                        )
                    ),
                    "time_created":
                        iso(
                            getattr(
                                volume,
                                "time_created",
                                None
                            )
                        ),
                    "attachment_status": attachment_status,
                    "attachment_type": attachment_type,
                    "attached_instance": attached_instance,
                    **backup_policy(volume.id, get_name(volume))
                })

        except Exception as exc:

            self.record_error(
                "Block Volumes",
                region,
                compartment["path"],
                exc
            )


        # ----------------------------------------------------
        # Boot Volumes
        # ----------------------------------------------------

        try:

            boots = self.get_all(
                clients["block"].list_boot_volumes,
                availability_domain=None,
                compartment_id=compartment["id"]
            )

            for volume in boots:

                instance_id = boot_attachments.get(volume.id)

                if instance_id:
                    attachment_status = "ATTACHED"
                    attached_instance = self.get_instance_name_cached(
                        clients["compute"],
                        instance_id
                    )
                else:
                    attachment_status = "DETACHED"
                    attached_instance = "N/A"

                result.append({
                    "resource_type": "Boot Volume",
                    "region": region,
                    "compartment": compartment["path"],
                    "name": get_name(volume),
                    "id": volume.id,
                    "state": lifecycle(volume),
                    "size_gb": safe(
                        getattr(
                            volume,
                            "size_in_gbs",
                            None
                        )
                    ),
                    "time_created":
                        iso(
                            getattr(
                                volume,
                                "time_created",
                                None
                            )
                        ),
                    "attachment_status": attachment_status,
                    # Boot volumes only ever attach as
                    # PARAVIRTUALIZED -- OCI does not support iSCSI
                    # boot volume attachments.
                    "attachment_type": (
                        "PARAVIRTUALIZED" if instance_id else "N/A"
                    ),
                    "attached_instance": attached_instance,
                    **backup_policy(volume.id, get_name(volume))
                })

        except Exception as exc:

            # Some OCI SDK versions require
            # availability_domain.
            #
            # We don't stop the entire report.
            self.record_error(
                "Boot Volumes",
                region,
                compartment["path"],
                exc
            )


        # ----------------------------------------------------
        # Volume Groups
        # ----------------------------------------------------

        try:

            groups = self.get_all(
                clients["block"].list_volume_groups,
                compartment_id=compartment["id"]
            )

            for group in groups:

                result.append({
                    "resource_type": "Volume Group",
                    "region": region,
                    "compartment": compartment["path"],
                    "name": get_name(group),
                    "id": group.id,
                    "state": lifecycle(group)
                })

        except Exception as exc:

            self.record_error(
                "Volume Groups",
                region,
                compartment["path"],
                exc
            )

        return result


    # ========================================================
    # OBJECT STORAGE
    # ========================================================

    def get_namespace(self, object_storage_client):

        with self.state_lock:
            if self.namespace_cache is not None:
                return self.namespace_cache

        try:
            namespace = object_storage_client.get_namespace().data
        except Exception as exc:
            self.record_error(
                "Object Storage",
                self.home_region,
                "ROOT",
                exc
            )
            namespace = None

        with self.state_lock:
            if self.namespace_cache is None:
                self.namespace_cache = namespace

        return self.namespace_cache


    def collect_object_storage(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        namespace = self.get_namespace(clients["object"])

        if not namespace:
            return result

        try:

            buckets = self.get_all(
                clients["object"].list_buckets,
                namespace_name=namespace,
                compartment_id=compartment["id"]
            )

            for bucket in buckets:

                try:

                    # approximateCount/approximateSize must be
                    # explicitly requested via `fields`, and are cheap
                    # (bucket metadata only). Deliberately not falling
                    # back to a full object listing to compute exact
                    # size -- that would mean iterating every object in
                    # every bucket, every region, every run, which
                    # doesn't scale for a daily health check.
                    details = clients["object"].get_bucket(
                        namespace_name=namespace,
                        bucket_name=bucket.name,
                        fields=["approximateCount", "approximateSize"]
                    ).data

                    size_bytes = safe(
                        getattr(details, "approximate_size", None), 0
                    ) or 0

                    object_count = safe(
                        getattr(details, "approximate_count", None), 0
                    ) or 0

                    result.append({
                        "resource_type": "Object Storage Bucket",
                        "region": region,
                        "compartment": compartment["path"],
                        "name": get_name(bucket),
                        "id": bucket.name,
                        "state": "ACTIVE",
                        "size_gb": round(size_bytes / (1024 ** 3), 3),
                        "object_count": object_count,
                        "storage_tier": safe(
                            getattr(details, "storage_tier", None),
                            "N/A"
                        ),
                        "public_access_type": safe(
                            getattr(details, "public_access_type", None),
                            "N/A"
                        ),
                        "time_created": iso(
                            getattr(details, "time_created", None)
                        )
                    })

                except Exception as exc:

                    self.record_error(
                        "Object Storage",
                        region,
                        compartment["path"],
                        exc
                    )

        except Exception as exc:

            self.record_error(
                "Object Storage",
                region,
                compartment["path"],
                exc
            )

        return result


    # ========================================================
    # DATABASE
    # ========================================================

    def collect_database(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        # DB Systems (bare metal / VM / Exadata)
        try:

            db_systems = self.get_all(
                clients["database"].list_db_systems,
                compartment_id=compartment["id"]
            )

            for db_system in db_systems:

                cpu_cores = safe(
                    getattr(db_system, "cpu_core_count", None), 0
                ) or 0

                memory_gb = safe(
                    getattr(db_system, "memory_size_in_gbs", None), 0
                ) or 0

                data_storage_gb = safe(
                    getattr(db_system, "data_storage_size_in_gbs", None), 0
                ) or 0

                reco_storage_gb = safe(
                    getattr(db_system, "reco_storage_size_in_gb", None), 0
                ) or 0

                result.append({
                    "resource_type": "DB System",
                    "region": region,
                    "compartment": compartment["path"],
                    "name": get_name(db_system),
                    "id": db_system.id,
                    "state": lifecycle(db_system),
                    "shape": safe(
                        getattr(db_system, "shape", None), "N/A"
                    ),
                    "db_version": safe(
                        getattr(db_system, "version", None), "N/A"
                    ),
                    "cpu_cores": cpu_cores,
                    "memory_gb": memory_gb,
                    "storage_gb": data_storage_gb + reco_storage_gb,
                    "time_created": iso(
                        getattr(db_system, "time_created", None)
                    )
                })

        except Exception as exc:

            self.record_error(
                "Database (DB Systems)",
                region,
                compartment["path"],
                exc
            )

        # Autonomous Databases
        try:

            adbs = self.get_all(
                clients["database"].list_autonomous_databases,
                compartment_id=compartment["id"]
            )

            for adb in adbs:

                cpu_cores = safe(
                    getattr(adb, "cpu_core_count", None), None
                )

                if cpu_cores is None:
                    cpu_cores = safe(
                        getattr(adb, "ocpu_count", None), 0
                    ) or 0

                storage_tb = safe(
                    getattr(adb, "data_storage_size_in_tbs", None), 0
                ) or 0

                # Autonomous Databases have no direct memory field --
                # memory scales with compute units instead, at a fixed
                # per-unit rate that differs between the older
                # OCPU-based and newer ECPU-based compute models.
                compute_model = safe(
                    getattr(adb, "compute_model", None), ""
                )

                if compute_model == "ECPU":
                    compute_count = safe(
                        getattr(adb, "compute_count", None), 0
                    ) or 0
                    memory_per_unit = safe(
                        getattr(
                            adb,
                            "memory_per_compute_unit_in_gbs",
                            None
                        ),
                        0
                    ) or 0
                else:
                    compute_count = cpu_cores
                    memory_per_unit = safe(
                        getattr(
                            adb,
                            "memory_per_oracle_compute_unit_in_gbs",
                            None
                        ),
                        0
                    ) or 0

                memory_gb = compute_count * memory_per_unit

                result.append({
                    "resource_type": "Autonomous Database",
                    "region": region,
                    "compartment": compartment["path"],
                    "name": get_name(adb),
                    "id": adb.id,
                    "state": lifecycle(adb),
                    "shape": safe(
                        getattr(adb, "db_workload", None), "N/A"
                    ),
                    "db_version": safe(
                        getattr(adb, "db_version", None), "N/A"
                    ),
                    "cpu_cores": cpu_cores,
                    "memory_gb": memory_gb,
                    "storage_gb": storage_tb * 1024,
                    "time_created": iso(
                        getattr(adb, "time_created", None)
                    )
                })

        except Exception as exc:

            self.record_error(
                "Database (Autonomous)",
                region,
                compartment["path"],
                exc
            )

        return result


    # ========================================================
    # FILE STORAGE
    # ========================================================

    def collect_file_storage(
        self,
        clients,
        region,
        compartment,
        availability_domains
    ):

        result = []

        for ad in availability_domains:

            try:

                file_systems = self.get_all(
                    clients["file"].list_file_systems,
                    compartment_id=compartment["id"],
                    availability_domain=ad
                )

                for fs in file_systems:

                    metered_bytes = safe(
                        getattr(fs, "metered_bytes", None), 0
                    ) or 0

                    result.append({
                        "resource_type": "File System",
                        "region": region,
                        "compartment": compartment["path"],
                        "name": get_name(fs),
                        "id": fs.id,
                        "state": lifecycle(fs),
                        "availability_domain": ad,
                        "size_gb": round(
                            metered_bytes / (1024 ** 3), 3
                        ),
                        "time_created": iso(
                            getattr(fs, "time_created", None)
                        )
                    })

            except Exception as exc:

                self.record_error(
                    "File Storage",
                    region,
                    compartment["path"],
                    exc
                )

        return result


    # ========================================================
    # BACKUPS
    # ========================================================

    def collect_backups(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        # Block volume backups
        try:

            backups = self.get_all(
                clients["block"].list_volume_backups,
                compartment_id=compartment["id"]
            )

            for backup in backups:

                created = getattr(
                    backup,
                    "time_created",
                    None
                )

                age_days = None

                if created:

                    age_days = (
                        now_utc() - created
                    ).total_seconds() / 86400

                result.append({
                    "resource_type": "Block Volume Backup",
                    "region": region,
                    "compartment":
                        compartment["path"],
                    "name": get_name(backup),
                    "id": backup.id,
                    "state": lifecycle(backup),
                    "size_gb": safe(
                        getattr(backup, "size_in_gbs", None), 0
                    ) or 0,
                    "time_created": iso(created),
                    "age_days":
                        round(age_days, 2)
                        if age_days is not None
                        else None,
                    "source_volume_id":
                        getattr(backup, "volume_id", None),
                    "backup_type":
                        safe(getattr(backup, "source_type", None))
                })

        except Exception as exc:

            self.record_error(
                "Block Backups",
                region,
                compartment["path"],
                exc
            )

        # Boot volume backups -- previously not collected at all,
        # so boot volume backup coverage/age was invisible to this
        # report even though block volume backups were checked.
        try:

            boot_backups = self.get_all(
                clients["block"].list_boot_volume_backups,
                compartment_id=compartment["id"]
            )

            for backup in boot_backups:

                created = getattr(
                    backup,
                    "time_created",
                    None
                )

                age_days = None

                if created:

                    age_days = (
                        now_utc() - created
                    ).total_seconds() / 86400

                result.append({
                    "resource_type": "Boot Volume Backup",
                    "region": region,
                    "compartment":
                        compartment["path"],
                    "name": get_name(backup),
                    "id": backup.id,
                    "state": lifecycle(backup),
                    "size_gb": safe(
                        getattr(backup, "size_in_gbs", None), 0
                    ) or 0,
                    "time_created": iso(created),
                    "age_days":
                        round(age_days, 2)
                        if age_days is not None
                        else None,
                    "source_volume_id":
                        getattr(backup, "boot_volume_id", None),
                    "backup_type":
                        safe(getattr(backup, "source_type", None))
                })

        except Exception as exc:

            self.record_error(
                "Boot Backups",
                region,
                compartment["path"],
                exc
            )

        return result


