    # ========================================================
    # LOAD BALANCERS
    # ========================================================

    def collect_load_balancers(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        # Classic Load Balancers
        try:

            lbs = self.get_all(
                clients["lb"].list_load_balancers,
                compartment_id=compartment["id"],
                # Some OCI SDK/API versions default list calls to a
                # reduced "simple" view, which can leave fields like
                # lifecycle_state, shape, and IP addresses empty even
                # though the load balancer itself is healthy. Requesting
                # "full" detail explicitly avoids that.
                detail="full"
            )

            for lb in lbs:

                result.append({
                    "resource_type":
                        "Load Balancer",
                    "lb_type": "Classic",
                    "region": region,
                    "compartment":
                        compartment["path"],
                    "name": get_name(lb),
                    "id": lb.id,
                    "state": lifecycle(lb),
                    "shape": safe(
                        getattr(
                            lb,
                            "shape_name",
                            None
                        ),
                        "N/A"
                    ),
                    "ip_addresses": [
                        safe(
                            getattr(
                                ip,
                                "ip_address",
                                None
                            )
                        )
                        for ip in
                        safe(
                            getattr(
                                lb,
                                "ip_addresses",
                                []
                            ),
                            []
                        )
                    ]
                })

        except Exception as exc:

            self.record_error(
                "Load Balancer",
                region,
                compartment["path"],
                exc
            )

        # Network Load Balancers -- a separate OCI service/API from
        # classic load balancers. Skipping this used to mean any NLBs
        # in the tenancy were simply invisible to this report, not
        # merely showing blank fields.
        try:

            nlbs = self.get_all(
                clients["nlb"].list_network_load_balancers,
                compartment_id=compartment["id"]
            )

            for nlb in nlbs:

                result.append({
                    "resource_type":
                        "Load Balancer",
                    "lb_type": "Network",
                    "region": region,
                    "compartment":
                        compartment["path"],
                    "name": get_name(nlb),
                    "id": nlb.id,
                    "state": lifecycle(nlb),
                    "shape": "Flexible (NLB)",
                    "ip_addresses": [
                        safe(
                            getattr(
                                ip,
                                "ip_address",
                                None
                            )
                        )
                        for ip in
                        safe(
                            getattr(
                                nlb,
                                "ip_addresses",
                                []
                            ),
                            []
                        )
                    ]
                })

        except Exception as exc:

            self.record_error(
                "Network Load Balancer",
                region,
                compartment["path"],
                exc
            )

        return result


    # ========================================================
    # ALARMS
    # ========================================================

    def collect_alarm_status(self, monitoring_client, compartment_id):

        statuses = self.get_all(
            monitoring_client.list_alarms_status,
            compartment_id=compartment_id
        )

        return {
            getattr(status, "alarm_id", None): safe(
                getattr(status, "status", None),
                "UNKNOWN"
            )
            for status in statuses
            if getattr(status, "alarm_id", None)
        }

    def collect_alarms(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        try:

            alarms = self.get_all(
                clients["monitoring"].list_alarms,
                compartment_id=compartment["id"]
            )

            alarm_statuses = self.collect_alarm_status(
                clients["monitoring"],
                compartment["id"]
            )

            for alarm in alarms:

                item = {
                    "region": region,
                    "compartment":
                        compartment["path"],
                    "name": get_name(alarm),
                    "id": alarm.id,
                    "state": safe(
                        getattr(
                            alarm,
                            "lifecycle_state",
                            None
                        )
                    ),
                    "severity": safe(
                        getattr(
                            alarm,
                            "severity",
                            None
                        )
                    ),
                    # OCI only reports a live status for enabled alarms,
                    # so an alarm missing from the status list is either
                    # disabled (worth surfacing -- it isn't monitoring
                    # anything) or has no data yet.
                    "status": alarm_statuses.get(alarm.id) or (
                        "DISABLED"
                        if getattr(alarm, "is_enabled", True) is False
                        else "NO DATA"
                    ),
                    "query": safe(
                        getattr(
                            alarm,
                            "query",
                            None
                        )
                    )
                }

                result.append(item)

        except Exception as exc:

            self.record_error(
                "Alarms",
                region,
                compartment["path"],
                exc
            )

        return result


    # ========================================================
    # ANNOUNCEMENTS
    # ========================================================

    def collect_announcements(self):

        print("[INFO] Collecting OCI announcements...")

        result = []

        # Announcements are tenancy-level.
        # Use home region endpoint.

        try:

            start_time = (
                now_utc()
                -
                datetime.timedelta(
                    days=self.announcement_days
                )
            )

            announcements, last_error = self.endpoint_call(
                lambda config: AnnouncementClient(
                    config,
                    retry_strategy=oci.retry.DEFAULT_RETRY_STRATEGY,
                    timeout=OCI_CLIENT_TIMEOUT
                ),
                lambda client: self.get_all(
                    client.list_announcements,
                    compartment_id=self.tenancy_id,
                    time_one_earliest_time=start_time
                )
            )

            if last_error:
                raise last_error

            for announcement in announcements:

                result.append({
                    "id":
                        getattr(
                            announcement,
                            "id",
                            None
                        ),
                    "title":
                        safe(
                            getattr(
                                announcement,
                                "summary",
                                None
                            )
                        ),
                    "description":
                        safe(
                            getattr(
                                announcement,
                                "description",
                                None
                            )
                        ),
                    "type":
                        safe(
                            getattr(
                                announcement,
                                "announcement_type",
                                None
                            )
                        ),
                    "lifecycle_state":
                        safe(
                            getattr(
                                announcement,
                                "lifecycle_state",
                                None
                            )
                        ),
                    "time_created":
                        iso(
                            getattr(
                                announcement,
                                "time_created",
                                None
                            )
                        ),
                    "time_one_start":
                        iso(
                            getattr(
                                announcement,
                                "time_one_value",
                                None
                            )
                        ),
                    "time_one_end":
                        iso(
                            getattr(
                                announcement,
                                "time_two_value",
                                None
                            )
                        )
                })

        except Exception as exc:

            self.record_error(
                "Announcements",
                self.home_region,
                "ROOT",
                exc
            )

        self.data["announcements"] = result

        return result


    # ========================================================
    # IAM
    # ========================================================

    def collect_iam(self):

        print("[INFO] Collecting IAM information...")

        iam = {
            "users": [],
            "groups": [],
            "policies": [],
            "dynamic_groups": []
        }

        # ----------------------------------------------------
        # Groups (collected first so user memberships can be
        # resolved to group names below)
        # ----------------------------------------------------

        group_name_by_id = {}

        try:

            groups = self.get_all(
                self.identity.list_groups,
                compartment_id=self.tenancy_id
            )

            for group in groups:

                iam["groups"].append({
                    "name": get_name(group),
                    "id": group.id,
                    "state": lifecycle(group)
                })

                group_name_by_id[group.id] = get_name(group)

        except Exception as exc:

            self.record_error(
                "IAM Groups",
                self.home_region,
                "ROOT",
                exc
            )

        # ----------------------------------------------------
        # Users
        # ----------------------------------------------------

        # The classic IAM ListUsers API keeps reporting lifecycle_state
        # ACTIVE for users deactivated in an identity domain, while the
        # OCI Console shows them as Inactive (driven by the domain's
        # SCIM `active` flag), so the domain status is authoritative.
        domain_active_by_ocid = self.collect_domain_user_status()

        try:

            users = self.get_all(
                self.identity.list_users,
                compartment_id=self.tenancy_id
            )

            for user in users:

                user_state = lifecycle(user)

                if domain_active_by_ocid.get(user.id) is False:
                    user_state = "INACTIVE"
                elif getattr(user, "inactive_status", None):
                    # Non-zero bitmask: suspended, disabled, blocked or
                    # locked -- all shown as Inactive in the Console.
                    user_state = "INACTIVE"

                try:
                    memberships = self.get_all(
                        self.identity.list_user_group_memberships,
                        compartment_id=self.tenancy_id,
                        user_id=user.id
                    )

                    group_names = [
                        group_name_by_id.get(
                            membership.group_id,
                            "Unknown Group"
                        )
                        for membership in memberships
                    ]

                except Exception:
                    group_names = []

                iam["users"].append({
                    "name": safe(
                        getattr(
                            user,
                            "name",
                            None
                        )
                    ),
                    "id": user.id,
                    "state": user_state,
                    "email":
                        safe(
                            getattr(
                                user,
                                "email",
                                None
                            )
                        ),
                    "mfa":
                        safe(
                            getattr(
                                user,
                                "is_mfa_activated",
                                None
                            ),
                            "UNKNOWN"
                        ),
                    "groups": group_names,
                    "time_created":
                        iso(
                            getattr(
                                user,
                                "time_created",
                                None
                            )
                        )
                })

        except Exception as exc:

            self.record_error(
                "IAM Users",
                self.home_region,
                "ROOT",
                exc
            )


        self.data["iam"] = iam

        return iam


    def collect_domain_user_status(self):
        """Map user OCID -> SCIM `active` flag across identity domains."""

        active_by_ocid = {}

        try:
            domains = self.get_all(
                self.identity.list_domains,
                compartment_id=self.tenancy_id,
                lifecycle_state="ACTIVE"
            )
        except Exception as exc:
            self.record_error(
                "IAM Identity Domains",
                self.home_region,
                "ROOT",
                exc
            )
            return active_by_ocid

        for domain in domains:

            try:
                client = oci.identity_domains.IdentityDomainsClient(
                    self.config,
                    service_endpoint=domain.url,
                    retry_strategy=oci.retry.DEFAULT_RETRY_STRATEGY,
                    timeout=OCI_CLIENT_TIMEOUT
                )

                start_index = 1
                page_size = 500

                while True:
                    page = client.list_users(
                        attributes="ocid,userName,active",
                        start_index=start_index,
                        count=page_size
                    ).data

                    resources = page.resources or []

                    for domain_user in resources:
                        if domain_user.ocid:
                            active_by_ocid[domain_user.ocid] = (
                                domain_user.active is not False
                            )

                    start_index += len(resources)

                    if (
                        not resources
                        or start_index > (page.total_results or 0)
                    ):
                        break

            except Exception as exc:
                self.record_error(
                    "IAM Domain Users",
                    self.home_region,
                    get_name(domain),
                    exc
                )

        return active_by_ocid


