def format_utilization(average, peak):
    """Render "avg / peak" for a utilization cell, or N/A."""
    if average is None:
        return "N/A"
    if peak is None:
        return html_escape(average)
    return (
        f'{html_escape(average)} '
        f'<span class="muted">/ {html_escape(peak)}</span>'
    )


def html_escape(value):

    if value is None:
        return "N/A"

    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


